/*
 * ai_pipeline.c - see ai_pipeline.h
 *
 * The feature definitions mirror modeloCWRU_corregido.py exactly:
 *   w   = w - mean(w)
 *   td  = [rms, peak, crest, kurtosis (excess, biased), skewness (biased), std]
 *   spec = |rFFT(w * hanning(1024))| / 1024
 *   fd  = log10(sum(band^2) + 1e-12) for the 16 bands of spec[1:] (32 bins each)
 */
#include "ai_pipeline.h"
#include "../include/modelo_pesos.h"   /* MEAN, SCALE, W1..W3, B1..B3 (generated by the training script) */
#include <math.h>

#define N      AI_WIN
#define PI_F   3.14159265358979323846f

/* ------------------------------------------------------------------ */
/* Hann window and FFT twiddles are built once on first use (RAM: 6 KB) */
/* ------------------------------------------------------------------ */
static float s_hann[N];
static float s_cos[N / 2], s_sin[N / 2];
static int   s_ready = 0;

static void ai_init_tables(void)
{
    if (s_ready) return;
    for (int n = 0; n < N; n++)
        s_hann[n] = 0.5f - 0.5f * cosf(2.0f * PI_F * (float)n / (float)(N - 1)); /* numpy.hanning */
    for (int k = 0; k < N / 2; k++) {
        s_cos[k] =  cosf(2.0f * PI_F * (float)k / (float)N);
        s_sin[k] = -sinf(2.0f * PI_F * (float)k / (float)N);
    }
    s_ready = 1;
}

#ifdef AI_USE_CMSIS_DSP
/* ---------------- STM32 path: CMSIS-DSP real FFT ---------------- */
#include "arm_math.h"
static arm_rfft_fast_instance_f32 s_rfft;
static int s_rfft_ready = 0;

static void ai_band_energy(const float *x, float *band_log10)
{
    static float out[N];
    float in[N];
    for (int n = 0; n < N; n++) in[n] = x[n] * s_hann[n];
    if (!s_rfft_ready) { arm_rfft_fast_init_f32(&s_rfft, N); s_rfft_ready = 1; }
    arm_rfft_fast_f32(&s_rfft, in, out, 0);
    /* packed output: out[0]=Re(X0), out[1]=Re(X512), then (Re,Im) of X1..X511 */
    for (int b = 0; b < AI_N_BANDS; b++) {
        float acc = 0.0f;
        for (int k = 1 + b * 32; k < 1 + (b + 1) * 32; k++) {
            float re, im;
            if (k == N / 2) { re = out[1]; im = 0.0f; }
            else            { re = out[2 * k]; im = out[2 * k + 1]; }
            float m = sqrtf(re * re + im * im) / (float)N;
            acc += m * m;
        }
        band_log10[b] = log10f(acc + 1e-12f);
    }
}
#else
/* ---------------- Portable path: radix-2 complex FFT ---------------- */
static void fft_inplace(float *re, float *im)
{
    /* bit reversal */
    for (int i = 1, j = 0; i < N; i++) {
        int bit = N >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) {
            float t = re[i]; re[i] = re[j]; re[j] = t;
            t = im[i]; im[i] = im[j]; im[j] = t;
        }
    }
    for (int len = 2; len <= N; len <<= 1) {
        int half = len >> 1, step = N / len;
        for (int i = 0; i < N; i += len) {
            for (int k = 0; k < half; k++) {
                float wr = s_cos[k * step], wi = s_sin[k * step];
                int a = i + k, b = i + k + half;
                float tr = re[b] * wr - im[b] * wi;
                float ti = re[b] * wi + im[b] * wr;
                re[b] = re[a] - tr; im[b] = im[a] - ti;
                re[a] += tr;        im[a] += ti;
            }
        }
    }
}

static void ai_band_energy(const float *x, float *band_log10)
{
    float re[N], im[N];
    for (int n = 0; n < N; n++) { re[n] = x[n] * s_hann[n]; im[n] = 0.0f; }
    fft_inplace(re, im);
    for (int b = 0; b < AI_N_BANDS; b++) {
        float acc = 0.0f;
        for (int k = 1 + b * 32; k < 1 + (b + 1) * 32; k++) {
            float m2 = (re[k] * re[k] + im[k] * im[k]) / ((float)N * (float)N);
            acc += m2;
        }
        band_log10[b] = log10f(acc + 1e-12f);
    }
}
#endif

/* ------------------------------------------------------------------ */
void ai_features(const float *window, float *feat)
{
    float w[N];
    ai_init_tables();

    float mean = 0.0f;
    for (int n = 0; n < N; n++) mean += window[n];
    mean /= (float)N;

    float m2 = 0.0f, m3 = 0.0f, m4 = 0.0f, peak = 0.0f;
    for (int n = 0; n < N; n++) {
        float d = window[n] - mean;
        w[n] = d;
        float d2 = d * d;
        m2 += d2; m3 += d2 * d; m4 += d2 * d2;
        float a = fabsf(d);
        if (a > peak) peak = a;
    }
    m2 /= (float)N; m3 /= (float)N; m4 /= (float)N;

    float rms = sqrtf(m2);
    feat[0] = rms;
    feat[1] = peak;
    feat[2] = peak / (rms + 1e-12f);
    feat[3] = (m2 > 0.0f) ? (m4 / (m2 * m2) - 3.0f) : 0.0f;       /* excess kurtosis */
    feat[4] = (m2 > 0.0f) ? (m3 / (m2 * sqrtf(m2))) : 0.0f;         /* skewness        */
    feat[5] = rms;                                                  /* population std  */

    ai_band_energy(w, &feat[6]);
}

/* ------------------------------------------------------------------ */
ai_class_t ai_classify_features(const float *feat, float *prob)
{
    float z[AI_N_FEAT], h1[32], h2[16], o[4];

    for (int i = 0; i < AI_N_FEAT; i++) z[i] = (feat[i] - MEAN[i]) / SCALE[i];

    for (int j = 0; j < 32; j++) {
        float s = B1[j];
        for (int i = 0; i < AI_N_FEAT; i++) s += z[i] * W1[i][j];
        h1[j] = s > 0.0f ? s : 0.0f;                    /* ReLU */
    }
    for (int j = 0; j < 16; j++) {
        float s = B2[j];
        for (int i = 0; i < 32; i++) s += h1[i] * W2[i][j];
        h2[j] = s > 0.0f ? s : 0.0f;
    }
    for (int j = 0; j < 4; j++) {
        float s = B3[j];
        for (int i = 0; i < 16; i++) s += h2[i] * W3[i][j];
        o[j] = s;
    }

    /* softmax (max-subtracted) */
    float mx = o[0];
    for (int j = 1; j < 4; j++) if (o[j] > mx) mx = o[j];
    float sum = 0.0f;
    for (int j = 0; j < 4; j++) { o[j] = expf(o[j] - mx); sum += o[j]; }

    int best = 0;
    for (int j = 0; j < 4; j++) {
        o[j] /= sum;
        if (o[j] > o[best]) best = j;
    }
    if (prob) for (int j = 0; j < 4; j++) prob[j] = o[j];
    return (ai_class_t)best;
}

ai_class_t ai_diagnose(const float *window, float *prob)
{
    float feat[AI_N_FEAT];
    ai_features(window, feat);
    return ai_classify_features(feat, prob);
}
